func createFlagDef(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		body, ok := parseFlagBody(c, true)
		if !ok {
			return
		}
		flag, err := st.CreateFlag(store.CreateFlagInput{
			Key:         body.key,
			Description: body.description,
			Labels:      body.labels,
		})
